import unusedImports from 'eslint-plugin-unused-imports';
import prettierConfig from 'eslint-config-prettier';
import tseslint from 'typescript-eslint';
import reactHooks from 'eslint-plugin-react-hooks';
import globals from 'globals';

export default tseslint.config(
  {
    ignores: [
      // Generated WASM files (auto-generated by wasm-pack — every one of these dirs is
      // gitignored build output; linting them produces warnings that regenerate on each build)
      'src/wasm/',
      'src/wasm-core/',
      'wasm-core/src/wasm-core/',
      'wasm-core/src/wasm/',
      'wasm-core/pkg/',
      'public/wasm/',

      // Build artifacts
      'dist/',
      'build/',
      'src-tauri/target/',
      'coverage/',

      // Node modules
      'node_modules/',
    ],
  },
  {
    plugins: {
      'unused-imports': unusedImports,
      'react-hooks': reactHooks,
    },
    rules: {
      // Classic pair only — NOT the full v7 "recommended" preset, which pulls in 17 React
      // Compiler-era rules (purity, set-state-in-render, immutability, etc.) unrelated to
      // this codebase's existing eslint-disable-next-line react-hooks/exhaustive-deps usage.
      'react-hooks/rules-of-hooks': 'error',
      'react-hooks/exhaustive-deps': 'warn',

      // Base rule is not TS-aware and misfires on unused-looking parameter names in
      // interface/type function signatures (e.g. `onChange: (e: Event) => void`) — no
      // options can fix that (no argsIgnorePattern support). unused-imports/no-unused-vars
      // below is TS-aware, correctly skips type-only signatures, and covers real unused
      // vars/args with its own ignore patterns — so it's the sole rule for this.
      'no-unused-vars': 'off',

      // Detect and warn on unused imports
      'unused-imports/no-unused-imports': 'warn',
      'unused-imports/no-unused-vars': [
        'warn',
        {
          vars: 'all',
          varsIgnorePattern: '^_',
          args: 'after-used',
          argsIgnorePattern: '^_',
        },
      ],
    },
  },
  {
    // Enforce logger usage instead of console.*. Scoped to application code only: the rule
    // points at src/utils/logger, a browser-side module, so it cannot apply to Node build
    // scripts under scripts/ (console is their real output channel) or to logger.ts itself,
    // which is where the console calls it wraps have to live.
    files: ['src/**/*.{js,jsx,ts,tsx}'],
    // Test files are excluded to match the type-aware block below: no config object supplies
    // a TS parser for them, so pulling *.test.tsx into the lint set only yields parse errors.
    // (Test files are currently unlinted entirely — separate gap, not this rule's business.)
    ignores: [
      'src/utils/logger.ts',
      '**/*.test.{ts,tsx,js,jsx}',
      '**/*.spec.{ts,tsx,js,jsx}',
      '**/*.d.ts',
    ],
    rules: {
      'no-restricted-syntax': [
        'warn',
        {
          selector:
            "CallExpression[callee.object.name='console'][callee.property.name=/^(log|info|debug|warn|error)$/]",
          message:
            'Use logger from src/utils/logger instead of console.* for environment-aware logging. See CLAUDE.md for migration guide.',
        },
      ],
    },
  },
  {
    // Type-aware rules — needs the TS project service, so scoped to files the
    // root tsconfig.json actually includes (excludes *.test.* — see tsconfig.json).
    files: ['src/**/*.{ts,tsx,js,jsx}'],
    ignores: ['**/*.test.{ts,tsx,js,jsx}', '**/*.spec.{ts,tsx,js,jsx}', '**/*.d.ts'],
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    plugins: {
      '@typescript-eslint': tseslint.plugin,
    },
    rules: {
      // Catches `x || default` silently treating an explicit falsy value (0, '', false)
      // as absent — use `x ?? default` when only null/undefined should fall back.
      '@typescript-eslint/prefer-nullish-coalescing': 'warn',
    },
  },
  {
    // JavaScript files have no type-check (`checkJs: false`), so a name a refactor removed
    // stays referenced until it throws at render — Translator.jsx's `handleQuickAddProperNoun`,
    // 2026-09-30. Test files use Vitest's globals and are unlinted anyway (see above).
    files: ['src/**/*.{js,jsx}'],
    ignores: ['**/*.test.{js,jsx}', '**/*.spec.{js,jsx}', '**/__tests__/**'],
    languageOptions: {
      globals: { ...globals.browser, ...globals.node },
    },
    rules: {
      'no-undef': 'error',
    },
  },
  // Prettier config (disables conflicting ESLint rules)
  prettierConfig
);
